import os
import re
import sys
from typing import NoReturn


def fail(message: str) -> NoReturn:
    sys.stderr.write(f"error: {message}\n")
    sys.exit(1)


def inside_cwd(path: str) -> bool:
    cwd = os.path.realpath(os.getcwd())
    target = os.path.realpath(path)
    try:
        return os.path.commonpath([cwd, target]) == cwd
    except ValueError:
        return False


def parse_width(text: str) -> int:
    if re.fullmatch(r"[0-9]+", text) is None:
        fail("WIDTH must be a whole number written in digits")
    try:
        width = int(text)
    except ValueError:
        fail("WIDTH is too large")
    if width < 1:
        fail("WIDTH must be at least 1")
    return width


def paragraphs(text: str) -> list[list[str]]:
    result: list[list[str]] = []
    current: list[str] = []
    for line in text.split("\n"):
        words = line.split()
        if words:
            current.extend(words)
        elif current:
            result.append(current)
            current = []
    if current:
        result.append(current)
    return result


def wrap(words: list[str], width: int) -> list[list[str]]:
    lines: list[list[str]] = []
    current: list[str] = []
    length = 0
    for word in words:
        if not current:
            current = [word]
            length = len(word)
        elif length + 1 + len(word) <= width:
            current.append(word)
            length += 1 + len(word)
        else:
            lines.append(current)
            current = [word]
            length = len(word)
    if current:
        lines.append(current)
    return lines


def justify(words: list[str], width: int) -> str:
    gaps = len(words) - 1
    spaces = width - sum(len(w) for w in words)
    base, extra = divmod(spaces, gaps)
    parts: list[str] = []
    for i, word in enumerate(words[:-1]):
        count = base + (1 if i < extra else 0)
        parts.append(word + " " * count)
    parts.append(words[-1])
    return "".join(parts)


def format_paragraph(words: list[str], width: int) -> list[str]:
    lines = wrap(words, width)
    out: list[str] = []
    last = len(lines) - 1
    for index, line in enumerate(lines):
        if index == last or len(line) == 1:
            out.append(" ".join(line))
        else:
            out.append(justify(line, width))
    return out


def main() -> int:
    if len(sys.argv) != 3:
        fail("expected arguments: FILE WIDTH")
    file_arg = sys.argv[1]
    width = parse_width(sys.argv[2])
    if not inside_cwd(file_arg):
        fail("FILE is outside the current directory")
    try:
        with open(os.path.realpath(file_arg), "rb") as handle:
            data = handle.read()
    except OSError:
        fail("cannot read FILE")
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        fail("FILE is not valid UTF-8")

    all_lines: list[str] = []
    for index, words in enumerate(paragraphs(text)):
        if index > 0:
            all_lines.append("")
        all_lines.extend(format_paragraph(words, width))

    output = "".join(line + "\n" for line in all_lines)
    sys.stdout.buffer.write(output.encode("utf-8"))
    sys.stdout.buffer.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())

import heapq
import os
import sys
from typing import NoReturn


class Failure(Exception):
    pass


def fail(message: str) -> NoReturn:
    raise Failure(message)


def inside_cwd(path: str) -> bool:
    cwd = os.path.realpath(os.getcwd())
    target = os.path.realpath(path)
    try:
        return os.path.commonpath([cwd, target]) == cwd
    except ValueError:
        return False


def parse(text: str) -> dict[str, set[str]]:
    graph: dict[str, set[str]] = {}
    for raw in text.split("\n"):
        if raw.strip() == "":
            continue
        if raw.count(":") != 1:
            fail(f"malformed line (needs exactly one colon): {raw!r}")
        left, right = raw.split(":")
        names = left.split()
        if len(names) != 1:
            fail(f"malformed line (needs exactly one name before colon): {raw!r}")
        name = names[0]
        if name in graph:
            fail(f"duplicate item: {name!r}")
        graph[name] = set(right.split())
    for deps in list(graph.values()):
        for dep in deps:
            graph.setdefault(dep, set())
    return graph


def order(graph: dict[str, set[str]]) -> list[str]:
    remaining: dict[str, int] = {}
    dependents: dict[str, list[str]] = {name: [] for name in graph}
    for name, deps in graph.items():
        remaining[name] = len(deps)
        for dep in deps:
            dependents[dep].append(name)
    ready = [name for name, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    result: list[str] = []
    while ready:
        name = heapq.heappop(ready)
        result.append(name)
        for user in dependents[name]:
            remaining[user] -= 1
            if remaining[user] == 0:
                heapq.heappush(ready, user)
    if len(result) != len(graph):
        fail("dependency cycle detected")
    return result


def run(argv: list[str]) -> str:
    if len(argv) != 1:
        fail("usage: PROGRAM FILE")
    path = argv[0]
    if not inside_cwd(path):
        fail(f"path is outside the current directory: {path!r}")
    try:
        with open(path, encoding="utf-8") as handle:
            text = handle.read()
    except (OSError, UnicodeDecodeError) as exc:
        fail(f"cannot read {path!r}: {exc}")
    graph = parse(text)
    result = order(graph)
    if not result:
        return ""
    return "\n".join(result) + "\n"


def main() -> int:
    try:
        output = run(sys.argv[1:])
    except Failure as exc:
        sys.stderr.buffer.write(f"error: {exc}\n".encode("utf-8"))
        sys.stderr.flush()
        return 1
    sys.stdout.buffer.write(output.encode("utf-8"))
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())

import * as fs from "node:fs";
import * as path from "node:path";

class Failure extends Error {}

function isInside(root: string, target: string): boolean {
  const rel = path.relative(root, target);
  if (rel === "" || path.isAbsolute(rel)) return false;
  return rel !== ".." && !rel.startsWith(".." + path.sep);
}

function parseWidth(text: string): number {
  if (!/^[0-9]+$/.test(text)) {
    throw new Failure("WIDTH must be a whole number of at least 1 written in digits");
  }
  const n = Number(text);
  if (!Number.isSafeInteger(n) || n < 1) {
    throw new Failure("WIDTH must be a whole number of at least 1 written in digits");
  }
  return n;
}

function splitParagraphs(text: string): string[][] {
  const paragraphs: string[][] = [];
  let words: string[] = [];
  let open = false;
  for (const line of text.split(/\r?\n/)) {
    if (line.trim() === "") {
      if (open) {
        paragraphs.push(words);
        words = [];
        open = false;
      }
    } else {
      open = true;
      for (const w of line.split(/\s+/)) {
        if (w !== "") words.push(w);
      }
    }
  }
  if (open) paragraphs.push(words);
  return paragraphs;
}

function wrap(words: string[], width: number): string[][] {
  const lines: string[][] = [];
  let cur: string[] = [];
  let len = 0;
  for (const w of words) {
    if (cur.length === 0) {
      cur = [w];
      len = w.length;
    } else if (len + 1 + w.length <= width) {
      cur.push(w);
      len += 1 + w.length;
    } else {
      lines.push(cur);
      cur = [w];
      len = w.length;
    }
  }
  if (cur.length > 0) lines.push(cur);
  return lines;
}

function justify(line: string[], width: number, isLast: boolean): string {
  if (isLast || line.length === 1) return line.join(" ");
  const gaps = line.length - 1;
  const letters = line.reduce((sum, w) => sum + w.length, 0);
  const spaces = width - letters;
  const base = Math.floor(spaces / gaps);
  const extra = spaces % gaps;
  let out = "";
  for (const [i, w] of line.entries()) {
    out += w;
    if (i < gaps) {
      out += " ".repeat(base + (i < extra ? 1 : 0));
    }
  }
  return out;
}

function run(): string {
  const args = process.argv.slice(2);
  if (args.length !== 2) {
    throw new Failure("usage: PROGRAM FILE WIDTH");
  }
  const fileArg = args[0] ?? "";
  const widthArg = args[1] ?? "";
  const width = parseWidth(widthArg);

  const cwd = process.cwd();
  let cwdReal: string;
  let fileReal: string;
  try {
    cwdReal = fs.realpathSync(cwd);
  } catch {
    throw new Failure("cannot resolve current directory");
  }
  try {
    fileReal = fs.realpathSync(path.resolve(cwd, fileArg));
  } catch {
    throw new Failure("cannot read FILE");
  }
  if (!isInside(cwdReal, fileReal)) {
    throw new Failure("FILE is outside the current directory");
  }

  let text: string;
  try {
    text = fs.readFileSync(fileReal, "utf8");
  } catch {
    throw new Failure("cannot read FILE");
  }

  const blocks = splitParagraphs(text).map((words) =>
    wrap(words, width)
      .map((line, i, all) => justify(line, width, i === all.length - 1))
      .join("\n"),
  );

  if (blocks.length === 0) return "";
  return blocks.join("\n\n") + "\n";
}

try {
  const out = run();
  process.stdout.write(out);
  process.exitCode = 0;
} catch (e) {
  const msg = e instanceof Failure ? e.message : "unexpected failure";
  process.stderr.write(`error: ${msg}\n`);
  process.exitCode = 1;
}

import re
import sys
from datetime import date
from pathlib import Path
from typing import NoReturn

DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
AMOUNT_RE = re.compile(r"(-?)([0-9]+)(?:\.([0-9]{2}))?")


def fail(text: str) -> NoReturn:
    sys.stderr.write(f"error: {text}\n")
    sys.exit(1)


def parse_date(text: str) -> date | None:
    m = DATE_RE.fullmatch(text)
    if m is None:
        return None
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def parse_amount(text: str) -> int | None:
    m = AMOUNT_RE.fullmatch(text)
    if m is None:
        return None
    cents = int(m.group(2)) * 100
    if m.group(3) is not None:
        cents += int(m.group(3))
    return -cents if m.group(1) == "-" else cents


def format_cents(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    a = abs(cents)
    return f"{sign}{a // 100}.{a % 100:02d}"


def main() -> None:
    args = sys.argv[1:]
    if len(args) != 1:
        fail("usage: PROGRAM FILE")

    try:
        cwd = Path.cwd().resolve(strict=True)
        target = Path(args[0]).resolve(strict=True)
    except (OSError, RuntimeError):
        fail("cannot read FILE")

    if not target.is_relative_to(cwd):
        fail("FILE is outside the current directory")

    try:
        data = target.read_bytes()
    except OSError:
        fail("cannot read FILE")

    balances: dict[str, int] = {}
    total = 0
    prev: date | None = None

    for line_no, raw in enumerate(data.split(b"\n"), start=1):
        try:
            line = raw.decode("utf-8")
        except UnicodeDecodeError:
            fail(f"line {line_no}")

        parts = line.split()
        if not parts:
            continue
        if len(parts) != 3:
            fail(f"line {line_no}")

        entry_date = parse_date(parts[0])
        amount = parse_amount(parts[2])
        if entry_date is None or amount is None:
            fail(f"line {line_no}")
        if prev is not None and entry_date < prev:
            fail(f"line {line_no}")
        prev = entry_date

        account = parts[1]
        balances[account] = balances.get(account, 0) + amount
        total += amount

    out: list[str] = []
    for account in sorted(balances):
        out.append(f"{account} {format_cents(balances[account])}")
    out.append(f"TOTAL {format_cents(total)}")

    sys.stdout.buffer.write("".join(line + "\n" for line in out).encode("utf-8"))
    sys.stdout.flush()
    sys.exit(0)


if __name__ == "__main__":
    main()

import sys
from pathlib import Path

DIGITS = "0123456789"


class MalformedError(Exception):
    pass


class Parser:
    def __init__(self, tokens: list[str]) -> None:
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> str | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self) -> str:
        tok = self.peek()
        if tok is None:
            raise MalformedError()
        self.pos += 1
        return tok

    def parse(self) -> int:
        value = self.expr()
        if self.peek() is not None:
            raise MalformedError()
        return value

    def expr(self) -> int:
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.advance()
            rhs = self.term()
            if op == "+":
                value = value + rhs
            else:
                value = value - rhs
        return value

    def term(self) -> int:
        value = self.unary()
        while self.peek() == "*":
            self.advance()
            value = value * self.unary()
        return value

    def unary(self) -> int:
        negate = False
        while self.peek() == "-":
            self.advance()
            negate = not negate
        value = self.primary()
        return -value if negate else value

    def primary(self) -> int:
        tok = self.advance()
        if tok == "(":
            value = self.expr()
            if self.advance() != ")":
                raise MalformedError()
            return value
        if tok[0] in DIGITS:
            return int(tok)
        raise MalformedError()


def tokenize(line: str) -> list[str]:
    tokens: list[str] = []
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c in " \t":
            i += 1
        elif c in DIGITS:
            j = i
            while j < n and line[j] in DIGITS:
                j += 1
            tokens.append(line[i:j])
            i = j
        elif c in "+-*()":
            tokens.append(c)
            i += 1
        else:
            raise MalformedError()
    return tokens


def fail(message: str) -> int:
    print(f"error: {message}", file=sys.stderr)
    return 1


def main() -> int:
    sys.set_int_max_str_digits(0)
    sys.setrecursionlimit(100000)

    args = sys.argv[1:]
    if len(args) != 1:
        return fail("expected exactly one argument: FILE")

    try:
        cwd = Path.cwd().resolve()
        target = (cwd / args[0]).resolve()
    except (OSError, RuntimeError):
        return fail("cannot resolve path")

    if not target.is_relative_to(cwd):
        return fail("path is outside the current directory")

    try:
        data = target.read_bytes()
        text = data.decode("utf-8")
    except (OSError, UnicodeDecodeError):
        return fail("cannot read file")

    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()

    results: list[str] = []
    for number, raw in enumerate(lines, start=1):
        line = raw[:-1] if raw.endswith("\r") else raw
        if line.strip(" \t") == "":
            continue
        try:
            value = Parser(tokenize(line)).parse()
        except (MalformedError, RecursionError):
            return fail(f"line {number}")
        results.append(str(value))

    sys.stdout.write("".join(r + "\n" for r in results))
    return 0


if __name__ == "__main__":
    sys.exit(main())

import * as fs from "node:fs";
import * as path from "node:path";

class Fail extends Error {}

function fail(message: string): never {
  throw new Fail(message);
}

function realOrFail(target: string, shown: string): string {
  try {
    return fs.realpathSync(target);
  } catch {
    return fail(`cannot read '${shown}'`);
  }
}

function readTextOrFail(target: string, shown: string): string {
  try {
    return fs.readFileSync(target, "utf8");
  } catch {
    return fail(`cannot read '${shown}'`);
  }
}

function isInsideCwd(target: string): boolean {
  const cwd = realOrFail(process.cwd(), ".");
  const rel = path.relative(cwd, target);
  if (rel === "" || path.isAbsolute(rel)) {
    return false;
  }
  if (rel === ".." || rel.indexOf(".." + path.sep) === 0) {
    return false;
  }
  return true;
}

function compareBytes(a: string, b: string): number {
  return Buffer.compare(Buffer.from(a, "utf8"), Buffer.from(b, "utf8"));
}

function run(args: string[]): string {
  const file = args[0];
  if (args.length !== 1 || file === undefined) {
    fail("usage: PROGRAM FILE");
  }

  const realFile = realOrFail(path.resolve(file), file);
  if (!isInsideCwd(realFile)) {
    fail(`'${file}' is outside the current directory`);
  }

  const text = readTextOrFail(realFile, file);

  // Parse lines into name -> dependency list.
  const edges: Record<string, string[]> = Object.create(null);
  const lines = text.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i] ?? "";
    if (line.trim() === "") {
      continue;
    }
    const colon = line.indexOf(":");
    if (colon < 0) {
      fail(`line ${i + 1} has no colon`);
    }
    const head = line.slice(0, colon).trim();
    if (!/^\S+$/.test(head)) {
      fail(`line ${i + 1} must begin with exactly one name`);
    }
    const tail = line.slice(colon + 1);
    if (tail.indexOf(":") >= 0) {
      fail(`line ${i + 1} has a colon in its dependencies`);
    }
    const trimmedTail = tail.trim();
    const list = trimmedTail === "" ? [] : trimmedTail.split(/\s+/);
    if (edges[head] !== undefined) {
      fail(`name '${head}' starts two lines`);
    }
    edges[head] = list;
  }

  // Collect all items, including names that appear only as dependencies.
  const names: string[] = [];
  const seen: Record<string, boolean> = Object.create(null);
  const addName = (name: string): void => {
    if (!seen[name]) {
      seen[name] = true;
      names.push(name);
    }
  };
  for (const name of Object.keys(edges)) {
    addName(name);
    for (const dep of edges[name] ?? []) {
      addName(dep);
    }
  }

  // Repeatedly pick the smallest ready item in byte (code point) order.
  const printed: Record<string, boolean> = Object.create(null);
  const order: string[] = [];
  while (order.length < names.length) {
    let best: string | undefined = undefined;
    for (const name of names) {
      if (printed[name]) {
        continue;
      }
      let ready = true;
      for (const dep of edges[name] ?? []) {
        if (!printed[dep]) {
          ready = false;
          break;
        }
      }
      if (!ready) {
        continue;
      }
      if (best === undefined || compareBytes(name, best) < 0) {
        best = name;
      }
    }
    if (best === undefined) {
      fail("dependencies contain a cycle");
    }
    printed[best] = true;
    order.push(best);
  }

  return order.map((name) => name + "\n").join("");
}

try {
  const output = run(process.argv.slice(2));
  process.stdout.write(output);
} catch (e) {
  const message = e instanceof Fail ? e.message : "could not complete";
  process.stderr.write(`error: ${message}\n`);
  process.exitCode = 1;
}

import * as fs from "node:fs";
import * as path from "node:path";
import { TextDecoder } from "node:util";

class Failure extends Error {}

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const AMOUNT_RE = /^(-?)(\d+)(?:\.(\d{2}))?$/;

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function validDate(s: string): boolean {
  if (!DATE_RE.test(s)) return false;
  const y = Number(s.slice(0, 4));
  const m = Number(s.slice(5, 7));
  const d = Number(s.slice(8, 10));
  if (y < 1 || m < 1 || m > 12 || d < 1) return false;
  const days = [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return d <= (days[m - 1] ?? 0);
}

function formatCents(c: bigint): string {
  const neg = c < BigInt(0);
  const a = neg ? -c : c;
  const whole = (a / BigInt(100)).toString();
  const frac = (a % BigInt(100)).toString().padStart(2, "0");
  return (neg ? "-" : "") + whole + "." + frac;
}

function compareBytes(a: string, b: string): number {
  return Buffer.compare(Buffer.from(a, "utf8"), Buffer.from(b, "utf8"));
}

function main(): void {
  const args = process.argv.slice(2);
  const arg = args[0];
  if (args.length !== 1 || arg === undefined) {
    throw new Failure("usage: PROGRAM FILE");
  }

  const cwd = fs.realpathSync(process.cwd());

  let target: string;
  try {
    target = fs.realpathSync(path.resolve(cwd, arg));
  } catch {
    throw new Failure(`cannot read ${arg}`);
  }

  const rel = path.relative(cwd, target);
  if (
    rel === "" ||
    path.isAbsolute(rel) ||
    rel === ".." ||
    rel.startsWith(".." + path.sep)
  ) {
    throw new Failure(`${arg} is outside the current directory`);
  }

  let bytes: Buffer;
  try {
    bytes = fs.readFileSync(target);
  } catch {
    throw new Failure(`cannot read ${arg}`);
  }

  let text: string;
  try {
    text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes);
  } catch {
    throw new Failure(`${arg} is not valid UTF-8`);
  }

  const lines = text.split("\n");
  const balances = new Map<string, bigint>();
  let total = BigInt(0);
  let prevDate: string | undefined;

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const line = lines[i] ?? "";
    const parts = line.split(/\s+/).filter((p) => p.length > 0);
    if (parts.length === 0) continue;

    const bad = (): Failure => new Failure(`line ${lineNo}`);

    if (parts.length !== 3) throw bad();
    const date = parts[0] ?? "";
    const account = parts[1] ?? "";
    const amount = parts[2] ?? "";

    if (!validDate(date)) throw bad();
    if (prevDate !== undefined && date < prevDate) throw bad();
    prevDate = date;

    const m = AMOUNT_RE.exec(amount);
    if (m === null) throw bad();
    const sign = m[1] ?? "";
    const intDigits = m[2] ?? "";
    const frac = m[3] ?? "00";

    let cents = BigInt(intDigits + frac);
    if (sign === "-") cents = -cents;

    balances.set(account, (balances.get(account) ?? BigInt(0)) + cents);
    total += cents;
  }

  const out: string[] = [];
  const accounts = Array.from(balances.keys()).sort(compareBytes);
  for (const acc of accounts) {
    const bal = balances.get(acc) ?? BigInt(0);
    out.push(`${acc} ${formatCents(bal)}`);
  }
  out.push(`TOTAL ${formatCents(total)}`);

  process.stdout.write(out.map((l) => l + "\n").join(""));
}

try {
  main();
} catch (err) {
  const msg = err instanceof Failure ? err.message : "unexpected failure";
  process.stderr.write(`error: ${msg}\n`);
  process.exitCode = 1;
}

use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn run(arg: &str) -> Result<String, String> {
    let cwd = env::current_dir()
        .and_then(|p| p.canonicalize())
        .map_err(|e| format!("cannot determine working directory: {}", e))?;

    let target = Path::new(arg)
        .canonicalize()
        .map_err(|e| format!("cannot access {}: {}", arg, e))?;

    if !target.starts_with(&cwd) {
        return Err(format!("{} is outside the working directory", arg));
    }

    let text = fs::read_to_string(&target)
        .map_err(|e| format!("cannot read {}: {}", arg, e))?;

    // item name -> set of dependency names
    let mut items: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut defined: HashSet<String> = HashSet::new();

    for (idx, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let lineno = idx + 1;

        let colon = line
            .find(':')
            .ok_or_else(|| format!("line {}: missing colon", lineno))?;

        let left = &line[..colon];
        let mut toks = left.split_whitespace();
        let name = match (toks.next(), toks.next()) {
            (Some(n), None) => n,
            _ => {
                return Err(format!(
                    "line {}: expected exactly one name before the colon",
                    lineno
                ))
            }
        };

        let right = &line[colon + 1..];
        if right.contains(':') {
            return Err(format!("line {}: unexpected colon", lineno));
        }

        if !defined.insert(name.to_string()) {
            return Err(format!("line {}: duplicate item {}", lineno, name));
        }

        let deps: BTreeSet<String> = right.split_whitespace().map(String::from).collect();

        items
            .entry(name.to_string())
            .or_default()
            .extend(deps.iter().cloned());

        for d in deps {
            items.entry(d).or_default();
        }
    }

    // In-degree (number of distinct unprinted dependencies) and reverse edges.
    let mut indeg: BTreeMap<&str, usize> = BTreeMap::new();
    let mut dependents: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for (k, deps) in &items {
        indeg.insert(k.as_str(), deps.len());
        for d in deps {
            dependents
                .entry(d.as_str())
                .or_default()
                .push(k.as_str());
        }
    }

    let mut ready: BTreeSet<&str> = BTreeSet::new();
    for (k, c) in &indeg {
        if *c == 0 {
            ready.insert(*k);
        }
    }

    let mut out = String::new();
    let mut printed = 0usize;

    loop {
        let next = match ready.iter().next() {
            Some(&x) => x,
            None => break,
        };
        ready.remove(next);

        out.push_str(next);
        out.push('\n');
        printed += 1;

        if let Some(ds) = dependents.get(next) {
            for &d in ds {
                let c = indeg.get_mut(d).expect("dependent must exist");
                *c -= 1;
                if *c == 0 {
                    ready.insert(d);
                }
            }
        }
    }

    if printed != items.len() {
        return Err("dependency cycle detected".to_string());
    }

    Ok(out)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        fail("usage: PROGRAM FILE");
    }

    let out = match run(&args[1]) {
        Ok(s) => s,
        Err(e) => fail(&e),
    };

    let stdout = io::stdout();
    let mut lock = stdout.lock();
    if lock.write_all(out.as_bytes()).and_then(|_| lock.flush()).is_err() {
        process::exit(1);
    }
}

use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn wrap<'a>(words: &[&'a str], width: usize) -> Vec<Vec<&'a str>> {
    let mut lines: Vec<Vec<&'a str>> = Vec::new();
    let mut cur: Vec<&'a str> = Vec::new();
    let mut cur_len: usize = 0;
    for &w in words {
        let wl = w.chars().count();
        if cur.is_empty() {
            cur.push(w);
            cur_len = wl;
        } else if cur_len + 1 + wl <= width {
            cur.push(w);
            cur_len += 1 + wl;
        } else {
            lines.push(std::mem::take(&mut cur));
            cur.push(w);
            cur_len = wl;
        }
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    lines
}

fn render(lines: &[Vec<&str>], width: usize, out: &mut String) {
    let count = lines.len();
    for (i, line) in lines.iter().enumerate() {
        let last = i + 1 == count;
        if last || line.len() == 1 {
            out.push_str(&line.join(" "));
        } else {
            let total: usize = line.iter().map(|w| w.chars().count()).sum();
            let gaps = line.len() - 1;
            let spaces = width.saturating_sub(total);
            let base = spaces / gaps;
            let extra = spaces % gaps;
            for (j, w) in line.iter().enumerate() {
                out.push_str(w);
                if j < gaps {
                    let n = base + if j < extra { 1 } else { 0 };
                    for _ in 0..n {
                        out.push(' ');
                    }
                }
            }
        }
        out.push('\n');
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        fail("usage: PROGRAM FILE WIDTH");
    }

    let w_str = &args[2];
    if w_str.is_empty() || !w_str.bytes().all(|b| b.is_ascii_digit()) {
        fail("WIDTH must be a whole number written in digits");
    }
    let width: usize = match w_str.parse::<usize>() {
        Ok(v) if v >= 1 => v,
        _ => fail("WIDTH must be at least 1"),
    };

    let cwd = match env::current_dir().and_then(|p| p.canonicalize()) {
        Ok(p) => p,
        Err(_) => fail("cannot determine the current directory"),
    };

    let file_path = match Path::new(&args[1]).canonicalize() {
        Ok(p) => p,
        Err(_) => fail("cannot read FILE"),
    };

    if !file_path.starts_with(&cwd) {
        fail("FILE is outside the current directory");
    }

    let text = match fs::read_to_string(&file_path) {
        Ok(t) => t,
        Err(_) => fail("cannot read FILE"),
    };

    // Collect paragraphs as lists of words.
    let mut paragraphs: Vec<Vec<&str>> = Vec::new();
    let mut cur: Vec<&str> = Vec::new();
    for line in text.lines() {
        let words: Vec<&str> = line.split_whitespace().collect();
        if words.is_empty() {
            if !cur.is_empty() {
                paragraphs.push(std::mem::take(&mut cur));
            }
        } else {
            cur.extend(words);
        }
    }
    if !cur.is_empty() {
        paragraphs.push(cur);
    }

    let mut out = String::new();
    for (pi, para) in paragraphs.iter().enumerate() {
        if pi > 0 {
            out.push('\n');
        }
        let lines = wrap(para, width);
        render(&lines, width, &mut out);
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    if handle.write_all(out.as_bytes()).is_err() || handle.flush().is_err() {
        process::exit(1);
    }
    process::exit(0);
}

#!/usr/bin/env python3
"""Transactional KEY=VALUE store driven by a script file."""

import os
import re
import sys
from typing import NoReturn

KEY_PATTERN: re.Pattern[str] = re.compile(r"[A-Za-z0-9_]+")


class Failure(Exception):
    """A failure that is reported as a single error line."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message: str = message


class CommandError(Exception):
    """A malformed or invalid command in the script."""


def fail(message: str) -> NoReturn:
    raise Failure(message)


def is_valid_key(text: str) -> bool:
    return KEY_PATTERN.fullmatch(text) is not None


def resolve_inside(arg: str, cwd: str) -> str:
    real: str = os.path.realpath(arg)
    if os.path.commonpath([cwd, real]) != cwd:
        fail("error: path is outside the current directory")
    return real


def read_text_file(path: str) -> str:
    with open(path, "rb") as handle:
        raw: bytes = handle.read()
    return raw.decode("utf-8")


def split_lines(text: str) -> list[str]:
    lines: list[str] = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    return lines


def load_database(path: str) -> dict[str, str]:
    store: dict[str, str] = {}
    try:
        text: str = read_text_file(path)
    except FileNotFoundError:
        return store
    except (OSError, UnicodeDecodeError):
        fail("error: cannot read DB")
    for number, line in enumerate(split_lines(text), start=1):
        key, sep, value = line.partition("=")
        if sep != "=" or not is_valid_key(key):
            fail(f"error: malformed line {number} in DB")
        store[key] = value
    return store


def write_database(path: str, store: dict[str, str]) -> None:
    data: bytes = "".join(f"{key}={store[key]}\n" for key in sorted(store)).encode("utf-8")
    try:
        with open(path, "wb") as handle:
            handle.write(data)
    except OSError:
        fail("error: cannot write DB")


class Session:
    def __init__(self, store: dict[str, str]) -> None:
        self.store: dict[str, str] = store
        self.snapshots: list[dict[str, str]] = []
        self.output: list[str] = []

    def execute(self, line: str) -> None:
        if line == "begin":
            self.snapshots.append(dict(self.store))
        elif line == "commit":
            if not self.snapshots:
                raise CommandError()
            self.snapshots.pop()
        elif line == "rollback":
            if not self.snapshots:
                raise CommandError()
            self.store = self.snapshots.pop()
        elif line.startswith("set "):
            key, sep, value = line[4:].partition(" ")
            if sep != " " or value == "" or not is_valid_key(key):
                raise CommandError()
            self.store[key] = value
        elif line.startswith("del "):
            key = line[4:]
            if not is_valid_key(key):
                raise CommandError()
            self.store.pop(key, None)
        elif line.startswith("get "):
            key = line[4:]
            if not is_valid_key(key):
                raise CommandError()
            self.output.append(self.store.get(key, "(none)"))
        else:
            raise CommandError()


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        fail("error: usage: PROGRAM DB SCRIPT")
    cwd: str = os.path.realpath(os.getcwd())
    db_path: str = resolve_inside(argv[0], cwd)
    script_path: str = resolve_inside(argv[1], cwd)

    try:
        script_text: str = read_text_file(script_path)
    except (OSError, UnicodeDecodeError):
        fail("error: cannot read SCRIPT")

    session = Session(load_database(db_path))

    for number, line in enumerate(split_lines(script_text), start=1):
        if line == "":
            continue
        try:
            session.execute(line)
        except CommandError:
            fail(f"error: line {number}")

    if session.snapshots:
        fail("error: unfinished transaction")

    write_database(db_path, session.store)

    out = sys.stdout.buffer
    for value in session.output:
        out.write((value + "\n").encode("utf-8"))
    out.flush()
    return 0


def cli() -> int:
    try:
        return main(sys.argv[1:])
    except Failure as failure:
        sys.stderr.write(failure.message + "\n")
        return 1


if __name__ == "__main__":
    sys.exit(cli())

import * as fs from "node:fs";
import * as path from "node:path";
import { TextDecoder } from "node:util";

class Fail extends Error {}

function fail(message: string): never {
  throw new Fail(message);
}

function isNotFound(e: unknown): boolean {
  return typeof e === "object" && e !== null && (e as { code?: unknown }).code === "ENOENT";
}

function isInside(full: string, root: string): boolean {
  if (full === root) return true;
  const prefix = root.endsWith(path.sep) ? root : root + path.sep;
  return full.startsWith(prefix);
}

// Resolves a path (following symlinks, including for not-yet-existing tails)
// and fails if the result is not inside root.
function resolveInside(target: string, root: string): string {
  let cur = path.resolve(target);
  const tail: string[] = [];
  for (;;) {
    let exists = true;
    try {
      fs.lstatSync(cur);
    } catch (e) {
      if (!isNotFound(e)) throw e;
      exists = false;
    }
    if (exists) {
      const full = path.join(fs.realpathSync(cur), ...tail);
      if (!isInside(full, root)) fail("path is outside the working directory");
      return full;
    }
    const parent = path.dirname(cur);
    if (parent === cur) fail("path is outside the working directory");
    tail.unshift(path.basename(cur));
    cur = parent;
  }
}

function readText(file: string): string {
  const bytes = fs.readFileSync(file);
  return new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes);
}

function splitLines(text: string): string[] {
  if (text === "") return [];
  const parts = text.split("\n");
  if (text.endsWith("\n")) parts.pop();
  return parts;
}

function run(scriptText: string, store: Map<string, string>): string[] {
  const out: string[] = [];
  const journals: Array<Array<[string, string | undefined]>> = [];

  const record = (key: string): void => {
    const top = journals[journals.length - 1];
    if (top !== undefined) top.push([key, store.get(key)]);
  };

  const lines = splitLines(scriptText);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i] ?? "";
    const n = i + 1;
    if (line === "") continue;

    if (line === "begin") {
      journals.push([]);
      continue;
    }
    if (line === "rollback") {
      const j = journals.pop();
      if (j === undefined) fail(`line ${n}`);
      for (const [key, prev] of j.reverse()) {
        if (prev === undefined) store.delete(key);
        else store.set(key, prev);
      }
      continue;
    }
    if (line === "commit") {
      const j = journals.pop();
      if (j === undefined) fail(`line ${n}`);
      const parent = journals[journals.length - 1];
      if (parent !== undefined) {
        for (const entry of j) parent.push(entry);
      }
      continue;
    }

    const setMatch = /^set ([A-Za-z0-9_]+) ([\s\S]+)$/.exec(line);
    if (setMatch !== null) {
      const key = setMatch[1] ?? "";
      const value = setMatch[2] ?? "";
      record(key);
      store.set(key, value);
      continue;
    }

    const delMatch = /^del ([A-Za-z0-9_]+)$/.exec(line);
    if (delMatch !== null) {
      const key = delMatch[1] ?? "";
      record(key);
      store.delete(key);
      continue;
    }

    const getMatch = /^get ([A-Za-z0-9_]+)$/.exec(line);
    if (getMatch !== null) {
      const key = getMatch[1] ?? "";
      out.push(`${store.get(key) ?? "(none)"}\n`);
      continue;
    }

    fail(`line ${n}`);
  }

  if (journals.length > 0) fail("unfinished transaction");
  return out;
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length !== 2) fail("usage: PROGRAM DB SCRIPT");
  const dbArg = args[0] ?? "";
  const scriptArg = args[1] ?? "";

  const root = fs.realpathSync(process.cwd());
  const dbPath = resolveInside(dbArg, root);
  const scriptPath = resolveInside(scriptArg, root);

  let scriptText: string;
  try {
    scriptText = readText(scriptPath);
  } catch {
    fail("cannot read script");
  }

  let dbText = "";
  try {
    dbText = readText(dbPath);
  } catch (e) {
    if (!isNotFound(e)) fail("cannot read database");
  }

  const store = new Map<string, string>();
  for (const line of splitLines(dbText)) {
    const m = /^([A-Za-z0-9_]+)=([\s\S]*)$/.exec(line);
    if (m === null) fail("malformed database line");
    store.set(m[1] ?? "", m[2] ?? "");
  }

  const out = run(scriptText, store);

  const body = [...store.keys()]
    .sort()
    .map((k) => `${k}=${store.get(k) ?? ""}\n`)
    .join("");
  fs.writeFileSync(dbPath, body, "utf8");

  process.stdout.write(out.join(""));
}

try {
  main();
  process.exitCode = 0;
} catch (e) {
  const message = e instanceof Error ? e.message : String(e);
  process.stderr.write(`error: ${message.replace(/[\r\n]+/g, " ")}\n`);
  process.exitCode = 1;
}

import * as fs from "node:fs";
import * as path from "node:path";

class ParseError extends Error {}

function fail(message: string): never {
  process.stderr.write(`error: ${message}\n`);
  process.exit(1);
}

type Op = "(" | "neg" | "+" | "-" | "*";

function prec(op: Op): number {
  switch (op) {
    case "(":
      return 0;
    case "+":
    case "-":
      return 1;
    case "*":
      return 2;
    case "neg":
      return 3;
  }
}

function applyTop(ops: Op[], vals: bigint[]): void {
  const op = ops.pop();
  if (op === undefined || op === "(") throw new ParseError();
  if (op === "neg") {
    const a = vals.pop();
    if (a === undefined) throw new ParseError();
    vals.push(-a);
    return;
  }
  const b = vals.pop();
  const a = vals.pop();
  if (a === undefined || b === undefined) throw new ParseError();
  switch (op) {
    case "+":
      vals.push(a + b);
      break;
    case "-":
      vals.push(a - b);
      break;
    case "*":
      vals.push(a * b);
      break;
  }
}

function pushBinary(ops: Op[], vals: bigint[], op: "+" | "-" | "*"): void {
  while (ops.length > 0) {
    const top = ops[ops.length - 1];
    if (top === undefined || top === "(" || prec(top) < prec(op)) break;
    applyTop(ops, vals);
  }
  ops.push(op);
}

function evaluate(line: string): bigint {
  const ops: Op[] = [];
  const vals: bigint[] = [];
  let expectOperand = true;
  let i = 0;

  while (i < line.length) {
    const c = line.charAt(i);

    if (c === " " || c === "\t") {
      i++;
      continue;
    }

    if (c >= "0" && c <= "9") {
      let j = i;
      while (j < line.length && line.charAt(j) >= "0" && line.charAt(j) <= "9") j++;
      if (!expectOperand) throw new ParseError();
      vals.push(BigInt(line.slice(i, j)));
      expectOperand = false;
      i = j;
      continue;
    }

    if (c === "-" && expectOperand) {
      ops.push("neg");
      i++;
      continue;
    }

    if (c === "+" || c === "-" || c === "*") {
      if (expectOperand) throw new ParseError();
      pushBinary(ops, vals, c);
      expectOperand = true;
      i++;
      continue;
    }

    if (c === "(") {
      if (!expectOperand) throw new ParseError();
      ops.push("(");
      expectOperand = true;
      i++;
      continue;
    }

    if (c === ")") {
      if (expectOperand) throw new ParseError();
      for (;;) {
        const top = ops[ops.length - 1];
        if (top === undefined) throw new ParseError();
        if (top === "(") {
          ops.pop();
          break;
        }
        applyTop(ops, vals);
      }
      expectOperand = false;
      i++;
      continue;
    }

    throw new ParseError();
  }

  if (expectOperand) throw new ParseError();
  while (ops.length > 0) {
    if (ops[ops.length - 1] === "(") throw new ParseError();
    applyTop(ops, vals);
  }
  if (vals.length !== 1) throw new ParseError();
  const result = vals[0];
  if (result === undefined) throw new ParseError();
  return result;
}

function tryEvaluate(line: string): bigint | null {
  try {
    return evaluate(line);
  } catch (e) {
    if (e instanceof ParseError) return null;
    throw e;
  }
}

function readInput(arg: string): string | null {
  try {
    const cwd = fs.realpathSync(process.cwd());
    const file = fs.realpathSync(path.resolve(cwd, arg));
    const rel = path.relative(cwd, file);
    if (
      rel === "" ||
      rel === ".." ||
      rel.startsWith(".." + path.sep) ||
      path.isAbsolute(rel)
    ) {
      return null;
    }
    return fs.readFileSync(file, "utf8");
  } catch {
    return null;
  }
}

function main(): void {
  const args = process.argv.slice(2);
  const arg = args[0];
  if (args.length !== 1 || arg === undefined) fail("usage: PROGRAM FILE");

  const text = readInput(arg);
  if (text === null) fail(`cannot read ${arg}`);

  const lines = text.split("\n");
  if (lines[lines.length - 1] === "") lines.pop();

  const out: string[] = [];
  for (let n = 0; n < lines.length; n++) {
    const line = lines[n];
    if (line === undefined || /^[ \t]*$/.test(line)) continue;
    const value = tryEvaluate(line);
    if (value === null) fail(`line ${n + 1}`);
    out.push(value.toString());
  }

  process.stdout.write(out.map((s) => s + "\n").join(""));
}

try {
  main();
} catch {
  fail("unexpected failure");
}

use std::collections::BTreeMap;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, Write};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn bad_line(n: usize) -> ! {
    fail(&format!("line {}", n))
}

fn is_leap(y: u32) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn parse_date(s: &str) -> Option<(u32, u32, u32)> {
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return None;
    }
    for (i, &c) in b.iter().enumerate() {
        if i == 4 || i == 7 {
            continue;
        }
        if !c.is_ascii_digit() {
            return None;
        }
    }
    let y: u32 = s[0..4].parse().ok()?;
    let m: u32 = s[5..7].parse().ok()?;
    let d: u32 = s[8..10].parse().ok()?;
    if y < 1 || m < 1 || m > 12 || d < 1 {
        return None;
    }
    let dim = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        _ => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
    };
    if d > dim {
        return None;
    }
    Some((y, m, d))
}

fn parse_amount(s: &str) -> Option<i128> {
    let (neg, rest) = match s.strip_prefix('-') {
        Some(r) => (true, r),
        None => (false, s),
    };
    let (ip, fp) = match rest.find('.') {
        Some(i) => (&rest[..i], Some(&rest[i + 1..])),
        None => (rest, None),
    };
    if ip.is_empty() || !ip.bytes().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let mut v: i128 = 0;
    for c in ip.bytes() {
        v = v.checked_mul(10)?.checked_add((c - b'0') as i128)?;
    }
    let frac: i128 = match fp {
        None => 0,
        Some(f) => {
            let fb = f.as_bytes();
            if fb.len() != 2 || !fb.iter().all(|c| c.is_ascii_digit()) {
                return None;
            }
            ((fb[0] - b'0') as i128) * 10 + ((fb[1] - b'0') as i128)
        }
    };
    let cents = v.checked_mul(100)?.checked_add(frac)?;
    Some(if neg { -cents } else { cents })
}

fn fmt_cents(c: i128) -> String {
    let a = c.unsigned_abs();
    format!(
        "{}{}.{:02}",
        if c < 0 { "-" } else { "" },
        a / 100,
        a % 100
    )
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 1 {
        fail("usage: PROGRAM FILE");
    }
    let arg = &args[0];

    let cwd = env::current_dir().unwrap_or_else(|_| fail("cannot determine working directory"));
    let cwd = fs::canonicalize(&cwd).unwrap_or_else(|_| fail("cannot determine working directory"));

    let path = fs::canonicalize(arg).unwrap_or_else(|_| fail("cannot read FILE"));
    if !path.starts_with(&cwd) {
        fail("FILE is outside the working directory");
    }

    let content = fs::read_to_string(&path).unwrap_or_else(|_| fail("cannot read FILE"));

    let mut balances: BTreeMap<String, i128> = BTreeMap::new();
    let mut total: i128 = 0;
    let mut prev: Option<(u32, u32, u32)> = None;

    for (idx, line) in content.lines().enumerate() {
        let n = idx + 1;
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }
        if parts.len() != 3 {
            bad_line(n);
        }
        let date = parse_date(parts[0]).unwrap_or_else(|| bad_line(n));
        if let Some(p) = prev {
            if date < p {
                bad_line(n);
            }
        }
        prev = Some(date);

        let amt = parse_amount(parts[2]).unwrap_or_else(|| bad_line(n));

        let e = balances.entry(parts[1].to_string()).or_insert(0);
        let nv = (*e)
            .checked_add(amt)
            .unwrap_or_else(|| fail("arithmetic overflow"));
        *e = nv;

        total = total
            .checked_add(amt)
            .unwrap_or_else(|| fail("arithmetic overflow"));
    }

    let mut out = String::new();
    for (acct, bal) in &balances {
        out.push_str(acct);
        out.push(' ');
        out.push_str(&fmt_cents(*bal));
        out.push('\n');
    }
    out.push_str("TOTAL ");
    out.push_str(&fmt_cents(total));
    out.push('\n');

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let _ = handle.write_all(out.as_bytes());
    let _ = handle.flush();
}

package main

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"unicode/utf8"
)

func fail(msg string) {
	fmt.Fprintln(os.Stderr, "error: "+msg)
	os.Exit(1)
}

func runeLen(s string) int {
	return utf8.RuneCountInString(s)
}

func justify(line []string, width int) string {
	total := 0
	for _, w := range line {
		total += runeLen(w)
	}
	gaps := len(line) - 1
	spaces := width - total
	base := spaces / gaps
	extra := spaces % gaps

	var b strings.Builder
	for k, w := range line {
		if k > 0 {
			n := base
			if k-1 < extra {
				n++
			}
			b.WriteString(strings.Repeat(" ", n))
		}
		b.WriteString(w)
	}
	return b.String()
}

func layout(words []string, width int) []string {
	var result []string
	i := 0
	for i < len(words) {
		lineWidth := runeLen(words[i])
		j := i + 1
		for j < len(words) && lineWidth+1+runeLen(words[j]) <= width {
			lineWidth += 1 + runeLen(words[j])
			j++
		}
		line := words[i:j]
		last := j == len(words)
		if last || len(line) == 1 {
			result = append(result, strings.Join(line, " "))
		} else {
			result = append(result, justify(line, width))
		}
		i = j
	}
	return result
}

func main() {
	if len(os.Args) != 3 {
		fail("usage: PROGRAM FILE WIDTH")
	}

	widthArg := os.Args[2]
	if widthArg == "" {
		fail("WIDTH must be a whole number of at least 1")
	}
	for i := 0; i < len(widthArg); i++ {
		if widthArg[i] < '0' || widthArg[i] > '9' {
			fail("WIDTH must be a whole number of at least 1")
		}
	}
	width, err := strconv.Atoi(widthArg)
	if err != nil || width < 1 {
		fail("WIDTH must be a whole number of at least 1")
	}

	name := os.Args[1]
	if name == "" {
		fail("cannot read FILE")
	}

	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot determine working directory")
	}

	var full string
	if filepath.IsAbs(name) {
		full = name
	} else {
		full = cwdReal + string(filepath.Separator) + name
	}

	fileReal, err := filepath.EvalSymlinks(full)
	if err != nil {
		fail("cannot read FILE")
	}

	rel, err := filepath.Rel(cwdReal, fileReal)
	if err != nil || rel == "." || rel == ".." ||
		strings.HasPrefix(rel, ".."+string(filepath.Separator)) ||
		filepath.IsAbs(rel) {
		fail("FILE is outside the current directory")
	}

	data, err := os.ReadFile(fileReal)
	if err != nil {
		fail("cannot read FILE")
	}

	var paragraphs [][]string
	var cur []string
	for _, line := range strings.Split(string(data), "\n") {
		if strings.TrimSpace(line) == "" {
			if len(cur) > 0 {
				paragraphs = append(paragraphs, cur)
				cur = nil
			}
			continue
		}
		cur = append(cur, strings.Fields(line)...)
	}
	if len(cur) > 0 {
		paragraphs = append(paragraphs, cur)
	}

	var out bytes.Buffer
	for pi, words := range paragraphs {
		if pi > 0 {
			out.WriteString("\n")
		}
		for _, l := range layout(words, width) {
			out.WriteString(l)
			out.WriteString("\n")
		}
	}

	if _, err := os.Stdout.Write(out.Bytes()); err != nil {
		fail("cannot write output")
	}
	os.Exit(0)
}

use std::cmp::Ordering;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::process;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, Debug)]
struct Big {
    neg: bool,
    mag: Vec<u64>, // little-endian limbs in base 1e9, no trailing zero limbs
}

impl Big {
    fn new(neg: bool, mut mag: Vec<u64>) -> Big {
        while let Some(&0) = mag.last() {
            mag.pop();
        }
        let neg = neg && !mag.is_empty();
        Big { neg, mag }
    }

    fn from_digits(s: &str) -> Big {
        let bytes = s.as_bytes();
        let mut mag = Vec::new();
        let mut end = bytes.len();
        while end > 0 {
            let start = if end >= 9 { end - 9 } else { 0 };
            let mut limb: u64 = 0;
            for &b in &bytes[start..end] {
                limb = limb * 10 + (b - b'0') as u64;
            }
            mag.push(limb);
            end = start;
        }
        Big::new(false, mag)
    }

    fn to_text(&self) -> String {
        if self.mag.is_empty() {
            return "0".to_string();
        }
        let mut s = String::new();
        if self.neg {
            s.push('-');
        }
        let n = self.mag.len();
        s.push_str(&format!("{}", self.mag[n - 1]));
        for i in (0..n - 1).rev() {
            s.push_str(&format!("{:09}", self.mag[i]));
        }
        s
    }
}

fn limb(v: &[u64], i: usize) -> u64 {
    if i < v.len() {
        v[i]
    } else {
        0
    }
}

fn cmp_mag(a: &[u64], b: &[u64]) -> Ordering {
    if a.len() != b.len() {
        return a.len().cmp(&b.len());
    }
    for i in (0..a.len()).rev() {
        if a[i] != b[i] {
            return a[i].cmp(&b[i]);
        }
    }
    Ordering::Equal
}

fn add_mag(a: &[u64], b: &[u64]) -> Vec<u64> {
    let n = a.len().max(b.len());
    let mut out = Vec::with_capacity(n + 1);
    let mut carry = 0u64;
    for i in 0..n {
        let s = limb(a, i) + limb(b, i) + carry;
        out.push(s % BASE);
        carry = s / BASE;
    }
    if carry > 0 {
        out.push(carry);
    }
    out
}

// Requires |a| >= |b|.
fn sub_mag(a: &[u64], b: &[u64]) -> Vec<u64> {
    let mut out = Vec::with_capacity(a.len());
    let mut borrow = 0i64;
    for i in 0..a.len() {
        let mut d = a[i] as i64 - limb(b, i) as i64 - borrow;
        if d < 0 {
            d += BASE as i64;
            borrow = 1;
        } else {
            borrow = 0;
        }
        out.push(d as u64);
    }
    out
}

fn mul_mag(a: &[u64], b: &[u64]) -> Vec<u64> {
    if a.is_empty() || b.is_empty() {
        return Vec::new();
    }
    let mut out = vec![0u64; a.len() + b.len()];
    for i in 0..a.len() {
        let mut carry = 0u64;
        for j in 0..b.len() {
            let cur = out[i + j] + a[i] * b[j] + carry;
            out[i + j] = cur % BASE;
            carry = cur / BASE;
        }
        let mut k = i + b.len();
        while carry > 0 {
            let cur = out[k] + carry;
            out[k] = cur % BASE;
            carry = cur / BASE;
            k += 1;
        }
    }
    out
}

fn add(x: &Big, y: &Big) -> Big {
    if x.neg == y.neg {
        Big::new(x.neg, add_mag(&x.mag, &y.mag))
    } else {
        match cmp_mag(&x.mag, &y.mag) {
            Ordering::Equal => Big::new(false, Vec::new()),
            Ordering::Greater => Big::new(x.neg, sub_mag(&x.mag, &y.mag)),
            Ordering::Less => Big::new(y.neg, sub_mag(&y.mag, &x.mag)),
        }
    }
}

fn negate(x: &Big) -> Big {
    Big::new(!x.neg, x.mag.clone())
}

fn sub(x: &Big, y: &Big) -> Big {
    add(x, &negate(y))
}

fn mul(x: &Big, y: &Big) -> Big {
    Big::new(x.neg != y.neg, mul_mag(&x.mag, &y.mag))
}

#[derive(Clone, PartialEq, Debug)]
enum Tok {
    Num(String),
    Plus,
    Minus,
    Star,
    LParen,
    RParen,
}

fn tokenize(line: &str) -> Option<Vec<Tok>> {
    let b = line.as_bytes();
    let mut i = 0;
    let mut toks = Vec::new();
    while i < b.len() {
        let c = b[i];
        match c {
            b' ' | b'\t' => i += 1,
            b'0'..=b'9' => {
                let s = i;
                while i < b.len() && b[i].is_ascii_digit() {
                    i += 1;
                }
                toks.push(Tok::Num(line[s..i].to_string()));
            }
            b'+' => {
                toks.push(Tok::Plus);
                i += 1;
            }
            b'-' => {
                toks.push(Tok::Minus);
                i += 1;
            }
            b'*' => {
                toks.push(Tok::Star);
                i += 1;
            }
            b'(' => {
                toks.push(Tok::LParen);
                i += 1;
            }
            b')' => {
                toks.push(Tok::RParen);
                i += 1;
            }
            _ => return None,
        }
    }
    Some(toks)
}

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<Tok> {
        self.toks.get(self.pos).cloned()
    }

    // expr := term (('+' | '-') term)*
    fn parse_expr(&mut self) -> Option<Big> {
        let mut v = self.parse_term()?;
        loop {
            match self.peek() {
                Some(Tok::Plus) => {
                    self.pos += 1;
                    let r = self.parse_term()?;
                    v = add(&v, &r);
                }
                Some(Tok::Minus) => {
                    self.pos += 1;
                    let r = self.parse_term()?;
                    v = sub(&v, &r);
                }
                _ => return Some(v),
            }
        }
    }

    // term := unary ('*' unary)*
    fn parse_term(&mut self) -> Option<Big> {
        let mut v = self.parse_unary()?;
        while let Some(Tok::Star) = self.peek() {
            self.pos += 1;
            let r = self.parse_unary()?;
            v = mul(&v, &r);
        }
        Some(v)
    }

    // unary := '-' unary | primary
    fn parse_unary(&mut self) -> Option<Big> {
        if let Some(Tok::Minus) = self.peek() {
            self.pos += 1;
            let v = self.parse_unary()?;
            return Some(negate(&v));
        }
        self.parse_primary()
    }

    // primary := number | '(' expr ')'
    fn parse_primary(&mut self) -> Option<Big> {
        match self.peek()? {
            Tok::Num(s) => {
                self.pos += 1;
                Some(Big::from_digits(&s))
            }
            Tok::LParen => {
                self.pos += 1;
                let v = self.parse_expr()?;
                if self.peek()? == Tok::RParen {
                    self.pos += 1;
                    Some(v)
                } else {
                    None
                }
            }
            _ => None,
        }
    }
}

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn fail_line(n: usize) -> ! {
    eprintln!("error: line {}", n);
    process::exit(1);
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 1 {
        fail("usage: PROGRAM FILE");
    }

    let cwd = match env::current_dir().and_then(|p| p.canonicalize()) {
        Ok(p) => p,
        Err(_) => fail("cannot determine current directory"),
    };

    let path = match Path::new(&args[0]).canonicalize() {
        Ok(p) => p,
        Err(_) => fail("cannot read file"),
    };

    if !path.starts_with(&cwd) {
        fail("file is outside the current directory");
    }

    let bytes = match fs::read(&path) {
        Ok(b) => b,
        Err(_) => fail("cannot read file"),
    };

    let text = String::from_utf8_lossy(&bytes);
    let mut out = String::new();

    for (idx, line) in text.lines().enumerate() {
        let n = idx + 1;
        if line.bytes().all(|c| c == b' ' || c == b'\t') {
            continue;
        }
        let toks = match tokenize(line) {
            Some(t) => t,
            None => fail_line(n),
        };
        let mut p = Parser { toks, pos: 0 };
        let v = match p.parse_expr() {
            Some(v) if p.pos == p.toks.len() => v,
            _ => fail_line(n),
        };
        out.push_str(&v.to_text());
        out.push('\n');
    }

    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
    process::exit(0);
}

package main

import (
	"errors"
	"fmt"
	"math/big"
	"os"
	"path/filepath"
	"strings"
)

func fail(msg string) {
	fmt.Fprintln(os.Stderr, "error: "+msg)
	os.Exit(1)
}

// insideCwd resolves arg (including .. and symbolic links) and returns the
// resolved path if it lies inside the current working directory.
func insideCwd(arg string) (string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", errors.New("cannot determine working directory")
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		return "", errors.New("cannot determine working directory")
	}
	// Do not use filepath.Join or Abs here: they clean ".." lexically before
	// symbolic links are resolved, which can give the wrong target.
	full := arg
	if !filepath.IsAbs(arg) {
		full = cwd + string(filepath.Separator) + arg
	}
	real, err := filepath.EvalSymlinks(full)
	if err != nil {
		return "", errors.New("cannot read file")
	}
	rel, err := filepath.Rel(cwdReal, real)
	if err != nil || filepath.IsAbs(rel) ||
		rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", errors.New("path is outside the working directory")
	}
	return real, nil
}

type parser struct {
	s   string
	pos int
}

func (p *parser) skip() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t') {
		p.pos++
	}
}

// peek returns the next significant byte, or -1 at end of line.
func (p *parser) peek() int {
	p.skip()
	if p.pos >= len(p.s) {
		return -1
	}
	return int(p.s[p.pos])
}

var errSyntax = errors.New("syntax error")

// expr := term (('+' | '-') term)*
func (p *parser) expr() (*big.Int, error) {
	v, err := p.term()
	if err != nil {
		return nil, err
	}
	for {
		c := p.peek()
		if c != '+' && c != '-' {
			return v, nil
		}
		p.pos++
		r, err := p.term()
		if err != nil {
			return nil, err
		}
		if c == '+' {
			v = new(big.Int).Add(v, r)
		} else {
			v = new(big.Int).Sub(v, r)
		}
	}
}

// term := unary ('*' unary)*
func (p *parser) term() (*big.Int, error) {
	v, err := p.unary()
	if err != nil {
		return nil, err
	}
	for p.peek() == '*' {
		p.pos++
		r, err := p.unary()
		if err != nil {
			return nil, err
		}
		v = new(big.Int).Mul(v, r)
	}
	return v, nil
}

// unary := '-' unary | primary
func (p *parser) unary() (*big.Int, error) {
	if p.peek() == '-' {
		p.pos++
		v, err := p.unary()
		if err != nil {
			return nil, err
		}
		return new(big.Int).Neg(v), nil
	}
	return p.primary()
}

// primary := number | '(' expr ')'
func (p *parser) primary() (*big.Int, error) {
	c := p.peek()
	switch {
	case c == '(':
		p.pos++
		v, err := p.expr()
		if err != nil {
			return nil, err
		}
		if p.peek() != ')' {
			return nil, errSyntax
		}
		p.pos++
		return v, nil
	case c >= '0' && c <= '9':
		start := p.pos
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
		v, ok := new(big.Int).SetString(p.s[start:p.pos], 10)
		if !ok {
			return nil, errSyntax
		}
		return v, nil
	default:
		return nil, errSyntax
	}
}

func evalLine(s string) (*big.Int, error) {
	p := &parser{s: s}
	v, err := p.expr()
	if err != nil {
		return nil, err
	}
	if p.peek() != -1 {
		return nil, errSyntax
	}
	return v, nil
}

func main() {
	if len(os.Args) != 2 {
		fail("usage: PROGRAM FILE")
	}

	path, err := insideCwd(os.Args[1])
	if err != nil {
		fail(err.Error())
	}

	data, err := os.ReadFile(path)
	if err != nil {
		fail("cannot read file")
	}

	lines := strings.Split(string(data), "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}

	var out strings.Builder
	for i, line := range lines {
		line = strings.TrimSuffix(line, "\r")
		if strings.Trim(line, " \t") == "" {
			continue
		}
		v, err := evalLine(line)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: line %d\n", i+1)
			os.Exit(1)
		}
		out.WriteString(v.String())
		out.WriteString("\n")
	}

	os.Stdout.WriteString(out.String())
	os.Exit(0)
}

