	fail(fmt.Sprintf("line %d", n))
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func parseDate(s string) bool {
	if len(s) != 10 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if i == 4 || i == 7 {
			if s[i] != '-' {
				return false
			}
		} else if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	y, err1 := strconv.Atoi(s[0:4])
	m, err2 := strconv.Atoi(s[5:7])
	d, err3 := strconv.Atoi(s[8:10])
	if err1 != nil || err2 != nil || err3 != nil {
		return false
	}
	if y < 1 || m < 1 || m > 12 || d < 1 {
		return false
	}
	var dim int
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		dim = 31
	case 4, 6, 9, 11:
		dim = 30
	case 2:
		if (y%4 == 0 && y%100 != 0) || y%400 == 0 {
			dim = 29
		} else {
			dim = 28
		}
	}
	return d <= dim
}

// parseAmount returns the amount in hundredths.
func parseAmount(s string) (*big.Int, bool) {
	body := s
	neg := false
	if strings.HasPrefix(body, "-") {
		neg = true
		body = body[1:]
	}
	var intPart, frac string
	if idx := strings.IndexByte(body, '.'); idx >= 0 {
		intPart = body[:idx]
		frac = body[idx+1:]
		if len(frac) != 2 {
			return nil, false
		}
	} else {
		intPart = body
		frac = "00"
	}
	if !allDigits(intPart) || !allDigits(frac) {
		return nil, false
	}
	v, ok := new(big.Int).SetString(intPart+frac, 10)
	if !ok {
		return nil, false
	}
	if neg {
		v.Neg(v)
	}
	return v, true
}

func formatAmount(c *big.Int) string {
	neg := c.Sign() < 0
	a := new(big.Int).Abs(c)
	q, r := new(big.Int).QuoRem(a, big.NewInt(100), new(big.Int))
	s := fmt.Sprintf("%s.%02d", q.String(), r.Int64())
	if neg {
		s = "-" + s
	}
	return s
}

func main() {
	if len(os.Args) != 2 {
		fail("usage: PROGRAM FILE")
	}
	arg := os.Args[1]

	resolved, err := filepath.EvalSymlinks(arg)
	if err != nil {
		fail("cannot read " + arg)
	}
	resolvedAbs, err := filepath.Abs(resolved)
	if err != nil {
		fail("cannot read " + arg)
	}
	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot determine working directory")
	}
	rel, err := filepath.Rel(cwdReal, resolvedAbs)
	if err != nil || rel == "." || rel == ".." ||
		strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		fail("path outside working directory: " + arg)
	}

	data, err := os.ReadFile(resolvedAbs)
	if err != nil {
		fail("cannot read " + arg)
	}

	content := string(data)
	lines := strings.Split(content, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}

	accounts := make(map[string]*big.Int)
	total := new(big.Int)
	prevDate := ""

	for i, line := range lines {
		n := i + 1
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		if !utf8.ValidString(line) {
			failLine(n)
		}
		if len(fields) != 3 {
			failLine(n)
		}
		date, acct, amt := fields[0], fields[1], fields[2]
		if !parseDate(date) {
			failLine(n)
		}
		if prevDate != "" && date < prevDate {
			failLine(n)
		}
		v, ok := parseAmount(amt)
		if !ok {
			failLine(n)
		}
		prevDate = date

		acc, exists := accounts[acct]
		if !exists {
			acc = new(big.Int)
			accounts[acct] = acc
		}
		acc.Add(acc, v)
		total.Add(total, v)
	}

	var out strings.Builder
	names := make([]string, 0, len(accounts))
	for name := range accounts {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		out.WriteString(name)
		out.WriteString(" ")
		out.WriteString(formatAmount(accounts[name]))
		out.WriteString("\n")
	}
	out.WriteString("TOTAL ")
	out.WriteString(formatAmount(total))
	out.WriteString("\n")

	os.Stdout.WriteString(out.String())
	os.Exit(0)
}

package main

import (
	"bufio"
	"container/heap"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"unicode/utf8"
)

type nameHeap []string

func (h nameHeap) Len() int            { return len(h) }
func (h nameHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h nameHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *nameHeap) Push(x any)         { *h = append(*h, x.(string)) }
func (h *nameHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func run() error {
	if len(os.Args) != 2 {
		return errors.New("usage: PROGRAM FILE")
	}
	arg := os.Args[1]

	cwd, err := os.Getwd()
	if err != nil {
		return fmt.Errorf("cannot determine working directory: %v", err)
	}
	realCwd, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		return fmt.Errorf("cannot resolve working directory: %v", err)
	}
	realFile, err := filepath.EvalSymlinks(arg)
	if err != nil {
		return fmt.Errorf("cannot read %q: %v", arg, err)
	}
	rel, err := filepath.Rel(realCwd, realFile)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		return fmt.Errorf("%q is outside the working directory", arg)
	}

	data, err := os.ReadFile(realFile)
	if err != nil {
		return fmt.Errorf("cannot read %q: %v", arg, err)
	}
	if !utf8.Valid(data) {
		return errors.New("input is not valid UTF-8")
	}

	items := map[string]bool{}
	defined := map[string]bool{}
	deps := map[string]map[string]bool{}

	lines := strings.Split(string(data), "\n")
	for n, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		colon := strings.IndexByte(line, ':')
		if colon < 0 {
			return fmt.Errorf("line %d: missing colon", n+1)
		}
		head := strings.Fields(line[:colon])
		if len(head) != 1 {
			return fmt.Errorf("line %d: expected exactly one name before colon", n+1)
		}
		name := head[0]
		if defined[name] {
			return fmt.Errorf("line %d: duplicate item %q", n+1, name)
		}
		defined[name] = true
		items[name] = true
		deps[name] = map[string]bool{}
		for _, d := range strings.Fields(line[colon+1:]) {
			if strings.IndexByte(d, ':') >= 0 {
				return fmt.Errorf("line %d: invalid dependency name %q", n+1, d)
			}
			deps[name][d] = true
			items[d] = true
		}
	}

	indeg := map[string]int{}
	dependents := map[string][]string{}
	for item := range items {
		for d := range deps[item] {
			indeg[item]++
			dependents[d] = append(dependents[d], item)
		}
	}

	h := &nameHeap{}
	for item := range items {
		if indeg[item] == 0 {
			*h = append(*h, item)
		}
	}
	heap.Init(h)

	order := make([]string, 0, len(items))
	for h.Len() > 0 {
		cur := heap.Pop(h).(string)
		order = append(order, cur)
		for _, dep := range dependents[cur] {
			indeg[dep]--
			if indeg[dep] == 0 {
				heap.Push(h, dep)
			}
		}
	}
	if len(order) != len(items) {
		return errors.New("dependency cycle detected")
	}

	w := bufio.NewWriter(os.Stdout)
	for _, item := range order {
		w.WriteString(item)
		w.WriteByte('\n')
	}
	return w.Flush()
}

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "error: "+err.Error())
		os.Exit(1)
	}
}

