package main

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode/utf8"
)

func fail(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n", msg)
	os.Exit(1)
}

// resolvePath resolves p (relative to base, which must be a real absolute
// directory) by walking its components, following symbolic links and
// handling ".." against the already-resolved directory.
func resolvePath(p, base string) (string, error) {
	cur := base
	if strings.HasPrefix(p, "/") {
		cur = "/"
	}
	queue := strings.Split(p, "/")
	hops := 0
	for len(queue) > 0 {
		c := queue[0]
		queue = queue[1:]
		switch c {
		case "", ".":
			continue
		case "..":
			cur = filepath.Dir(cur)
			continue
		}
		next := filepath.Join(cur, c)
		fi, err := os.Lstat(next)
		if err == nil && fi.Mode()&os.ModeSymlink != 0 {
			hops++
			if hops > 255 {
				return "", errors.New("too many symbolic links")
			}
			target, err := os.Readlink(next)
			if err != nil {
				return "", err
			}
			if strings.HasPrefix(target, "/") {
				cur = "/"
			}
			queue = append(strings.Split(target, "/"), queue...)
			continue
		}
		if err != nil && !os.IsNotExist(err) {
			return "", err
		}
		cur = next
	}
	return cur, nil
}

func isInside(p, base string) bool {
	rel, err := filepath.Rel(base, p)
	if err != nil {
		return false
	}
	if rel == "." || rel == ".." || filepath.IsAbs(rel) ||
		strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return false
	}
	return true
}

func resolveInside(arg, base string) string {
	resolved, err := resolvePath(arg, base)
	if err != nil {
		fail(fmt.Sprintf("cannot resolve path %q", arg))
	}
	if !isInside(resolved, base) {
		fail(fmt.Sprintf("path %q is outside the working directory", arg))
	}
	return resolved
}

func validKey(k string) bool {
	if k == "" {
		return false
	}
	for i := 0; i < len(k); i++ {
		c := k[i]
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func splitLines(s []byte) []string {
	if len(s) == 0 {
		return nil
	}
	lines := strings.Split(string(s), "\n")
	if strings.HasSuffix(string(s), "\n") {
		lines = lines[:len(lines)-1]
	}
	return lines
}

func cloneState(m map[string]string) map[string]string {
	c := make(map[string]string, len(m))
	for k, v := range m {
		c[k] = v
	}
	return c
}

func main() {
	if len(os.Args) != 3 {
		fail("usage: PROGRAM DB SCRIPT")
	}

	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot determine working directory")
	}

	dbPath := resolveInside(os.Args[1], cwdReal)
	scriptPath := resolveInside(os.Args[2], cwdReal)

	scriptData, err := os.ReadFile(scriptPath)
	if err != nil || !utf8.Valid(scriptData) {
		fail("cannot read script")
	}

	state := make(map[string]string)
	dbData, err := os.ReadFile(dbPath)
	if err != nil {
		if !os.IsNotExist(err) {
			fail("cannot read database")
		}
	} else {
		if !utf8.Valid(dbData) {
			fail("malformed database")
		}
		for i, line := range splitLines(dbData) {
			idx := strings.IndexByte(line, '=')
			if idx < 0 || !validKey(line[:idx]) {
				fail(fmt.Sprintf("malformed database line %d", i+1))
			}
			state[line[:idx]] = line[idx+1:]
		}
	}

	var out bytes.Buffer
	var stack []map[string]string

	for i, line := range splitLines(scriptData) {
		n := i + 1
		if line == "" {
			continue
		}
		bad := func() {
			fail(fmt.Sprintf("line %d", n))
		}
		switch {
		case line == "begin":
			stack = append(stack, cloneState(state))
		case line == "commit":
			if len(stack) == 0 {
				bad()
			}
			stack = stack[:len(stack)-1]
		case line == "rollback":
			if len(stack) == 0 {
				bad()
			}
			top := len(stack) - 1
			state = stack[top]
			stack = stack[:top]
		case strings.HasPrefix(line, "set "):
			rest := line[len("set "):]
			sp := strings.IndexByte(rest, ' ')
			if sp < 0 {
				bad()
			}
			key, val := rest[:sp], rest[sp+1:]
			if !validKey(key) || val == "" {
				bad()
			}
			state[key] = val
		case strings.HasPrefix(line, "del "):
			key := line[len("del "):]
			if !validKey(key) {
				bad()
			}
			delete(state, key)
		case strings.HasPrefix(line, "get "):
			key := line[len("get "):]
			if !validKey(key) {
				bad()
			}
			if v, ok := state[key]; ok {
				out.WriteString(v)
				out.WriteByte('\n')
			} else {
				out.WriteString("(none)\n")
			}
		default:
			bad()
		}
	}

	if len(stack) > 0 {
		fail("unfinished transaction")
	}

	keys := make([]string, 0, len(state))
	for k := range state {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var db bytes.Buffer
	for _, k := range keys {
		db.WriteString(k)
		db.WriteByte('=')
		db.WriteString(state[k])
		db.WriteByte('\n')
	}
	if err := os.WriteFile(dbPath, db.Bytes(), 0o644); err != nil {
		fail("cannot write database")
	}

	os.Stdout.Write(out.Bytes())
	os.Exit(0)
}

use std::collections::BTreeMap;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, ErrorKind, Write};
use std::path::{Path, PathBuf};
use std::process;

type Map = BTreeMap<String, String>;
type Undo = Vec<(String, Option<String>)>;

enum Cmd<'a> {
    Set(&'a str, &'a str),
    Del(&'a str),
    Get(&'a str),
    Begin,
    Commit,
    Rollback,
}

fn valid_key(k: &str) -> bool {
    !k.is_empty() && k.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_')
}

fn parse(line: &str) -> Option<Cmd<'_>> {
    if line == "begin" {
        return Some(Cmd::Begin);
    }
    if line == "commit" {
        return Some(Cmd::Commit);
    }
    if line == "rollback" {
        return Some(Cmd::Rollback);
    }
    if let Some(rest) = line.strip_prefix("set ") {
        let (k, v) = rest.split_once(' ')?;
        if valid_key(k) && !v.is_empty() {
            return Some(Cmd::Set(k, v));
        }
        return None;
    }
    if let Some(k) = line.strip_prefix("del ") {
        return if valid_key(k) { Some(Cmd::Del(k)) } else { None };
    }
    if let Some(k) = line.strip_prefix("get ") {
        return if valid_key(k) { Some(Cmd::Get(k)) } else { None };
    }
    None
}

fn resolve_inside(cwd: &Path, p: &Path) -> Result<PathBuf, String> {
    let shown = p.display();
    let resolved = match fs::symlink_metadata(p) {
        Ok(_) => fs::canonicalize(p).map_err(|_| format!("cannot access {}", shown))?,
        Err(e) if e.kind() == ErrorKind::NotFound => {
            let name = p
                .file_name()
                .ok_or_else(|| format!("invalid path {}", shown))?;
            let parent = match p.parent() {
                Some(d) if !d.as_os_str().is_empty() => d,
                _ => Path::new("."),
            };
            let dir =
                fs::canonicalize(parent).map_err(|_| format!("cannot access {}", shown))?;
            dir.join(name)
        }
        Err(_) => return Err(format!("cannot access {}", shown)),
    };
    if !resolved.starts_with(cwd) {
        return Err(format!("path outside working directory: {}", shown));
    }
    Ok(resolved)
}

fn execute(script: &str, map: &mut Map) -> Result<String, String> {
    let mut out = String::new();
    let mut logs: Vec<Undo> = Vec::new();
    for (idx, line) in script.lines().enumerate() {
        let n = idx + 1;
        if line.is_empty() {
            continue;
        }
        let cmd = parse(line).ok_or_else(|| format!("line {}", n))?;
        match cmd {
            Cmd::Begin => logs.push(Vec::new()),
            Cmd::Commit => {
                let log = logs.pop().ok_or_else(|| format!("line {}", n))?;
                if let Some(parent) = logs.last_mut() {
                    parent.extend(log);
                }
            }
            Cmd::Rollback => {
                let log = logs.pop().ok_or_else(|| format!("line {}", n))?;
                for (k, old) in log.into_iter().rev() {
                    match old {
                        Some(v) => {
                            map.insert(k, v);
                        }
                        None => {
                            map.remove(&k);
                        }
                    }
                }
            }
            Cmd::Set(k, v) => {
                let old = map.insert(k.to_string(), v.to_string());
                if let Some(top) = logs.last_mut() {
                    top.push((k.to_string(), old));
                }
            }
            Cmd::Del(k) => {
                let old = map.remove(k);
                if let Some(top) = logs.last_mut() {
                    top.push((k.to_string(), old));
                }
            }
            Cmd::Get(k) => match map.get(k) {
                Some(v) => {
                    out.push_str(v);
                    out.push('\n');
                }
                None => out.push_str("(none)\n"),
            },
        }
    }
    if !logs.is_empty() {
        return Err("unfinished transaction".to_string());
    }
    Ok(out)
}

fn run() -> Result<(), String> {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        return Err("usage: PROGRAM DB SCRIPT".to_string());
    }
    let cwd = env::current_dir()
        .and_then(|d| fs::canonicalize(d))
        .map_err(|_| "cannot determine working directory".to_string())?;

    let db_path = resolve_inside(&cwd, Path::new(&args[0]))?;
    let script_path = resolve_inside(&cwd, Path::new(&args[1]))?;

    let script =
        fs::read_to_string(&script_path).map_err(|_| "cannot read script".to_string())?;

    let text = match fs::read_to_string(&db_path) {
        Ok(t) => t,
        Err(e) if e.kind() == ErrorKind::NotFound => String::new(),
        Err(_) => return Err("cannot read database".to_string()),
    };

    let mut map = Map::new();
    for line in text.lines() {
        let (k, v) = line
            .split_once('=')
            .ok_or_else(|| "malformed database line".to_string())?;
        if !valid_key(k) {
            return Err("malformed database line".to_string());
        }
        map.insert(k.to_string(), v.to_string());
    }

    let output = execute(&script, &mut map)?;

    let mut data = String::new();
    for (k, v) in &map {
        data.push_str(k);
        data.push('=');
        data.push_str(v);
        data.push('\n');
    }
    fs::write(&db_path, data).map_err(|_| "cannot write database".to_string())?;

    let mut stdout = io::stdout();
    stdout
        .write_all(output.as_bytes())
        .and_then(|_| stdout.flush())
        .map_err(|_| "cannot write output".to_string())?;
    Ok(())
}

fn main() {
    if let Err(msg) = run() {
        eprintln!("error: {}", msg);
        process::exit(1);
    }
}
